  const title = furniture ? 'Furniture Shop' : tiles ? 'Tiles Shop' : 'Interiors & Decorations';
  const profile = place?.attributes?.businessProfile || {}; const common = profile.common || {}; const specific = profile.categorySpecific || {};
  const defaultHighlights = [{ icon: '✦', title: 'Quality Selection', description: 'Thoughtfully selected products and materials' }, { icon: '▦', title: 'Wide Range', description: 'Options for different styles and budgets' }, { icon: '₹', title: 'Expert Guidance', description: 'Friendly help choosing the right fit' }, { icon: '✓', title: 'Trusted Service', description: 'Support from selection to delivery' }];
  const [saving, setSaving] = useState(false); const [error, setError] = useState(''); const [message, setMessage] = useState('');
