  const [form, setForm] = useState({ name: place?.name || '', tagline: common.tagline || '', about: place?.description || common.about || '', phone: place?.phone || '', whatsapp: place?.socialLinks?.whatsapp || '', email: place?.email || '', website: place?.website || '', address: place?.address || '', logo: place?.logo || common.logo || '', cover: place?.coverImage || common.coverImage || '', aboutImage: common.aboutImage || '', gallery: place?.images || common.gallery || [], videos: common.videos || [], highlights: specific.highlights || defaultHighlights, categories: specific.shopCategories || [], products: specific.featuredItems || [], services: specific.serviceCards || [], portfolio: specific.portfolio || [], social: { ...(place?.socialLinks || {}), ...(common.socialMedia || {}) } });
  const set = (key, value) => setForm((current) => ({ ...current, [key]: value }));
