    const payload = { name: form.name, category: categoryId || place?.category?._id || place?.category, subcategory: place?.subcategory?._id || place?.subcategory || undefined, address: form.address, description: form.about, phone: form.phone, email: form.email || undefined, website: form.website || undefined, logo: form.logo || undefined, coverImage: form.cover || undefined, images: form.gallery.slice(0, 10), services: categorySpecific.serviceCards || [], facilities: [], socialLinks: { ...form.social, whatsapp: form.whatsapp || undefined }, location: { ...location, area: location.area || null }, attributes: { ...(place?.attributes || {}), businessProfile: { ...profile, businessType: propertyType, common: { ...common, businessName: form.name, tagline: form.tagline, about: form.about, aboutImage: form.aboutImage, logo: form.logo, coverImage: form.cover, gallery: form.gallery.slice(0, 10), videos: form.videos, socialMedia: { ...form.social, whatsapp: form.whatsapp } }, categorySpecific } } };
    try { if (place?._id) await api.put(`/places/${place._id}`, payload); else await api.post('/places', payload); setMessage(place?._id ? 'Business updated successfully.' : 'Business submitted for approval.'); if (!place?._id) setTimeout(() => navigate('/business/dashboard'), 1000); }
